#include "turret142_internal.h"
/* $060E62: airborne body, independent gun, ballistic shots and two crash paths. */
static void tick(struct EntityPool*,struct NativeEntity*,void*);
void t42_schedule(struct NativeEntity*e,unsigned s){e->tick=tick;enemy_schedule(&e->payload.enemy,s);}
struct NativeEntity*t42_allocate(struct WeaponWorld*w,struct EntityRef p,enum EntityInsert o,const struct PlayerTransform*t,unsigned s){struct NativeEntity*e=enemy_allocate(w,p,o,t,tick);if(e){struct EnemyActor*q=&e->payload.enemy;uint8_t*b=(uint8_t*)&q->turret142;for(unsigned i=0;i<sizeof(q->turret142);i++)b[i]=255;q->selector=q->scale=65535;t42_schedule(e,s);}return e;}
struct NativeEntity*t42_child(struct WeaponWorld*w,struct NativeEntity*e,unsigned s,int copy){/* $04AE without $05DD02 retains allocator coordinates. */struct PlayerTransform blank={.x=-256,.y=513*256,.priority=0,.facing=0,.display_group=255};return t42_allocate(w,entity_ref(e),ENTITY_FIRST_CHILD,copy?&e->payload.enemy.actor.transform:&blank,s);}
void t42_entry(struct EnemyActor*q,uint16_t n){if(n!=65535){animation_begin(&q->actor.animation,n);q->actor.movement_flags|=32;}}
void t42_start(struct EnemyActor*q,unsigned n){t42_entry(q,turret142_entries[n]);}
void t42_defense(struct EnemyActor*q,unsigned n){q->actor.defense=n==65535?0:turret142_bindings[n].defense;q->actor.defense_count=n==65535?0:turret142_bindings[n].count;}
void t42_attack(struct EnemyActor*q,unsigned n){if(n==65535)q->actor.attack=0;else{q->attack_set=(struct HitAttackSet){turret142_bindings[n].attack,turret142_bindings[n].count};q->actor.attack=&q->attack_set;}}
int16_t t42_rank(struct WeaponWorld*w,struct EnemyActor*q,unsigned n){struct InteractionWorld*r=w->interactions;if(!r||!r->rank_valid||n>=T42R_COUNT){enemy_fault(w);return 0;}unsigned i=(interaction_rank(w,&q->actor,runtime_owner_turret142[n]))*8+(q->source_flags&3)*2;const struct Turret142RankData*t=&turret142_rank[n];if(t->choices)i=t->choices[i+((uint8_t)(r->player_count_flag-1)&1)]*8+((tk_random(w)&14)>>1);else i+=(r->player_count_flag&2)>>1;return (int16_t)t->values[i];}
struct Context{struct WeaponWorld*w;struct NativeEntity*e;};
static uint32_t read(void*ctx,unsigned f,unsigned width){(void)width;struct Context*c=ctx;if(f!=T42F_13_1){enemy_fault(c->w);return 0;}return c->e->payload.enemy.actor.hit.flags;}
static int field(void*ctx,unsigned f,unsigned width,enum AnimationFieldOperation op,uint32_t v){struct Context*c=ctx;uint32_t old=read(ctx,f,width);if(op==AN_FIELD_AND)v&=old;else if(op==AN_FIELD_OR)v|=old;else if(op==AN_FIELD_XOR)v^=old;else if(op!=AN_FIELD_SET)return enemy_fault(c->w);c->e->payload.enemy.actor.hit.flags=v;return !c->w->fault;}
static int bind(void*ctx,unsigned k,uint32_t v){struct Context*c=ctx;unsigned n=v==0xffffffffu?65535:v;if(n!=65535&&n>=8)return enemy_fault(c->w);if(k==AN_DEFENSE)t42_defense(&c->e->payload.enemy,n);else if(k==AN_ATTACK)t42_attack(&c->e->payload.enemy,n);else return enemy_fault(c->w);return 1;}
static int sound(void*ctx,uint16_t n,int stop){struct Context*c=ctx;return c->w->sound&&c->w->sound(c->w->scene,n,stop)?1:enemy_fault(c->w);}
static int call(void*ctx,unsigned n,struct Animation*an){(void)an;struct Context*c=ctx;struct EnemyActor*q=&c->e->payload.enemy;if(n==T42C_609C2)return t42_child(c->w,c->e,T42_SMOKE,1)!=0;if(n==T42C_60B12)return t42_stamp(c->w,c->e,T42S_B_DEAD0+q->turret142.variant);if(n==T42C_60C9A)return t42_stamp(c->w,c->e,T42S_C_DEAD0+q->turret142.variant);return enemy_fault(c->w);}
int t42_animate(struct WeaponWorld*w,struct NativeEntity*e){struct WeaponActor*a=&e->payload.enemy.actor;if(a->animation.cursor==65535)return 0;struct Context c={w,e};struct AnimationOwner o={.context=&c,.read=read,.write=field,.bind=bind,.sound=sound,.call=call};int done=animation_step(&a->animation,&turret142_program,&o);if(a->animation.fault)enemy_fault(w);return done;}
int t42_outside(struct WeaponWorld*w,struct WeaponActor*a,unsigned i,int force){return interaction_outside(w,a,turret142_bounds[i],force);}
static int target(struct WeaponWorld*w,struct EnemyActor*q){q->turret142.target_y=256+16*(q->params[1]&15);struct WeaponActor query={.transform=q->actor.transform};if(!(q->actor.hit.flags&64)){if(!w->interactions||!w->interactions->terrain)return enemy_fault(w);transform_integer_offset(&query.transform,w->interactions->terrain->delta_x,-w->interactions->terrain->delta_y);}int i=enemy_nearest_x(w,&query,0);if(i>=0)q->turret142.target_x=tk_word((w->players[i]->actor.transform.x>>8)-w->camera_x);return !w->fault;}
/* Before a source movement call, the actor still holds the preceding screen
 * word. Ancestors/players have already run; do not apply this to their reads. */
static int16_t pending_x(struct WeaponWorld*w,struct WeaponActor*a){if(!(a->hit.flags&64)&&(!w->interactions||!w->interactions->terrain)){enemy_fault(w);return 0;}return tk_word(tk_sx(w,a)+((a->hit.flags&64)?0:w->interactions->terrain->delta_x));}
static int16_t pending_y(struct WeaponWorld*w,struct WeaponActor*a){if(!(a->hit.flags&64)&&(!w->interactions||!w->interactions->terrain)){enemy_fault(w);return 0;}return tk_word(tk_sy(w,a)-((a->hit.flags&64)?0:w->interactions->terrain->delta_y));}
static int16_t distance(struct WeaponWorld*w,struct EnemyActor*q){/* $05E23A signed-word max, unsigned half-min. */int16_t x=tk_word(pending_x(w,&q->actor)-q->turret142.target_x),y=tk_word(pending_y(w,&q->actor)-q->turret142.target_y);if(x<0)x=tk_word(-x);if(y<0)y=tk_word(-y);if(x<=y){int16_t z=x;x=y;y=z;}return tk_word(x+((uint16_t)y>>1));}
static int steer(struct WeaponWorld*w,struct EnemyActor*q,int fast){struct WeaponActor*a=&q->actor;int16_t dx=tk_word(q->turret142.target_x-pending_x(w,a)),dy=tk_word(q->turret142.target_y-pending_y(w,a));q->selector=(enemy_angle(dx>>1,dy>>1)+tk_faced(a,q->params[4]&31))&255;int16_t speed=tk_word(distance(w,q)*(fast?16:8));int16_t vx=tk_word(((int32_t)boss_trig[1][q->selector]*speed)>>8),vy=tk_word(((int32_t)boss_trig[0][q->selector]*speed)>>8);a->ax=tk_word(vx-a->vx)>>(fast?4:3);a->ay=fast?16:tk_word(vy-a->vy)>>4;return interaction_move(w,a,WMOVE_POINT)>=0;}
static int orbit(struct WeaponWorld*w,struct EnemyActor*q){q->selector=(q->selector-4)&255;q->actor.vx=0;q->actor.vy=tk_word((int32_t)boss_trig[0][q->selector]*64>>8);return interaction_move(w,&q->actor,WMOVE_POINT)>=0;}
static int palette(struct WeaponWorld*w,struct EnemyActor*q){q->turret142.cycle++;if(q->turret142.cycle==2){uint16_t x=q->turret142.palettes[0];q->turret142.palettes[0]=q->turret142.palettes[1];q->turret142.palettes[1]=x;q->turret142.cycle=0;}q->turret142.hits<<=1;if(q->actor.hit.flags&8){q->turret142.hits|=1;q->actor.hit.flags&=247;if(!tk_sound(w,0x108d))return 0;}q->actor.palette=(q->turret142.hits&3)==1?0x18a:q->turret142.palettes[0];return 1;}
static void pose(struct EnemyActor*q){int16_t v=q->actor.vx;unsigned i=v<-192?0:v<-128?1:v<-64?2:v<64?3:v<128?4:v<192?5:6;q->turret142.pose=q->actor.transform.facing&1?6-i:i;}
static void body(struct EnemyActor*q){t42_entry(q,turret142_body[q->turret142.pose<=6?q->turret142.pose:0]);}
static int shoot(struct WeaponWorld*w,struct NativeEntity*e){struct EnemyActor*q=&e->payload.enemy;if(q->turret142.wait>0){q->turret142.wait=tk_word(q->turret142.wait-1);return 1;}if(q->turret142.count==255){q->turret142.delay=t42_rank(w,q,T42R_SHOT_DELAY);q->turret142.count=t42_rank(w,q,T42R_SHOT_COUNT);}if((int8_t)q->turret142.delay>0){q->turret142.delay--;return !w->fault;}if(!q->turret142.count){q->turret142.count=255;q->turret142.wait=t42_rank(w,q,T42R_WAIT);return !w->fault;}if(!t42_child(w,e,T42_SHELL,1)||!t42_child(w,e,T42_BARREL,1))return 0;q->turret142.delay=t42_rank(w,q,T42R_SHOT_DELAY);q->turret142.count--;return !w->fault;}
static int gate(struct WeaponWorld*w,struct EnemyActor*q){q->turret142.timer=tk_word(q->turret142.timer-2);if(q->turret142.timer<=0)return 1;if(!w->secondary_view_valid){enemy_fault(w);return 0;}return tk_word(w->secondary_x_offset-q->turret142.scroll_start)>q->turret142.travel;}
static int stop(struct WeaponWorld*w){return w->sound&&w->sound(w->scene,0x10e8,1)?1:enemy_fault(w);}
static int enter(struct WeaponWorld*w,struct NativeEntity*e){struct EnemyActor*q=&e->payload.enemy;struct WeaponActor*a=&q->actor;
 switch(a->state){
 case T42_ROOT:if(!tk_sound(w,0x10e8))return 0;q->turret142.palettes[0]=0x187;q->turret142.palettes[1]=0x188;q->turret142.hits=0;a->palette=0x18a;a->transform.priority=0x8000;m4_reset(a);if(interaction_move(w,a,WMOVE_POINT)<0)return 0;a->transform.facing=q->params[0]&3;q->turret142.target_x=tk_sx(w,a);q->turret142.target_y=tk_sy(w,a);if(!target(w,q))return 0;a->hit.hp=t42_rank(w,q,T42R_HP);q->turret142.wait=t42_rank(w,q,T42R_INITIAL_WAIT);q->turret142.count=255;t42_defense(q,T42B_BODY);a->phase=0;if(!w->secondary_view_valid)return enemy_fault(w);q->turret142.timer=(q->params[2]<<6)&32767;q->turret142.travel=q->params[3]<<4;q->turret142.scroll_start=w->secondary_x_offset;if(!t42_child(w,e,T42_GUN,0))return 0;a->state=T42_ACTIVE;break;
 case T42_ACTIVE:case T42_ORBIT:break;
 case T42_DEAD:q->turret142.target_y=511;t42_start(q,T42A_T_DEAD);break;
 case T42_DEAD_B:q->turret142.target_x=320;q->turret142.target_y=352;q->params[4]<<=1;t42_start(q,T42A_T_DEAD);break;
 case T42_EXIT:q->turret142.target_y=511;break;
 default:return enemy_fault(w);
 }return !w->fault;
}
static int frame(struct WeaponWorld*w,struct NativeEntity*e,unsigned s){struct EnemyActor*q=&e->payload.enemy;struct WeaponActor*a=&q->actor;
 if(s==T42_ACTIVE||s==T42_ORBIT){if(!target(w,q)||(s==T42_ACTIVE?!steer(w,q,0):!orbit(w,q))||!palette(w,q))return 0;pose(q);body(q);t42_animate(w,e);if(a->hit.flags&1)t42_schedule(e,q->params[2]==255?T42_DEAD_B:T42_DEAD);if(!shoot(w,e))return 0;/* Source proximity and gate writes intentionally follow (and may replace) death. */if(s==T42_ACTIVE&&distance(w,q)<=8)t42_schedule(e,T42_ORBIT);if(s==T42_ORBIT&&distance(w,q)>16)t42_schedule(e,T42_ACTIVE);if(gate(w,q))t42_schedule(e,T42_EXIT);if(t42_outside(w,a,0,0)){a->phase=255;entity_delete(w->entities,e);}return !w->fault;}
 if(!steer(w,q,s!=T42_DEAD_B)||!palette(w,q))return 0;pose(q);if(s==T42_EXIT)body(q);t42_animate(w,e);
 if(s==T42_EXIT){if(t42_outside(w,a,0,1)){a->phase=255;if(!stop(w))return 0;entity_delete(w->entities,e);}return !w->fault;}
 if((s==T42_DEAD&&tk_sy(w,a)>=432)||(s==T42_DEAD_B&&tk_word(a->transform.x>>8)>=992)){struct NativeEntity*n=boss_fx_spawn(w,entity_ref(e),ENTITY_FIRST_CHILD,&a->transform,BFX_SMOKE);if(!n)return 0;transform_integer_offset(&n->payload.enemy.actor.transform,0,-16);if(!boss_fx_pattern(w,entity_ref(e),&a->transform,BP_TURRET142_DEATH)||!tk_sound(w,0x102f)||!stop(w))return 0;a->phase=255;if(s==T42_DEAD){/* $061482's +facing16 and $09A7CC's opposite16 cancel. */if(!item_spawn_drop(w,&a->transform,q->params[5],q->params[6],q->params[7],1,0))return 0;}else if(!t42_child(w,e,T42_CRASH,1))return 0;entity_delete(w->entities,e);return !w->fault;}
 if(!(w->frame_phase&3)){struct NativeEntity*n=boss_fx_pattern(w,entity_ref(e),&a->transform,BP_TURRET142_HIT);if(!n)return 0;transform_integer_offset(&n->payload.enemy.actor.transform,tk_faced(a,40),-24);}if(t42_outside(w,a,0,0)){if(!tk_sound(w,0x102f)||!stop(w))return 0;a->phase=255;entity_delete(w->entities,e);}return !w->fault;
}
static void tick(struct EntityPool*p,struct NativeEntity*e,void*world){struct WeaponWorld*w=world;if(w->fault)return;struct EnemyActor*q=&e->payload.enemy;for(unsigned b=0;b<8;b++){unsigned s=q->actor.state;if(s==T42_DELETE||s==T42_DELETE_TREE){if(s==T42_DELETE_TREE)entity_delete_children(p,e);entity_delete(p,e);return;}if(q->entry){q->entry=0;int r=s<T42_GUN?enter(w,e):s<T42_A_NEW?t42_parts_enter(w,e):obstacle_enter(w,e);if(!r||w->fault)return;if(r==2)continue;}if(!e->active||e->deleting)return;s=q->actor.state;if(s<T42_GUN)frame(w,e,s);else if(s<T42_A_NEW)t42_parts_frame(w,e,s);else obstacle_frame(w,e,s);return;}enemy_fault(w);}
int turret142_spawn(struct WeaponWorld*w,struct EntityRef p,enum EntityInsert o,uint16_t id,const struct PlayerTransform*t,const uint8_t params[8]){unsigned s,v;if(id==142){s=T42_ROOT;v=0;}else if(id==144||id==145){s=T42_A_NEW;v=id-144;}else if(id>=146&&id<=148){s=T42_B_NEW;v=id-146;}else if(id==149||id==150){s=T42_C_NEW;v=id-149;}else if(id>=276&&id<=280){s=T42_PROP_NEW;v=id-276;}else return enemy_fault(w);struct NativeEntity*e=t42_allocate(w,p,o,t,s);if(!e)return 0;e->payload.enemy.turret142.variant=v;if(params)for(unsigned i=0;i<8;i++)e->payload.enemy.params[i]=params[i];return 1;}
int turret142_has_children(struct WeaponWorld*w,const struct NativeEntity*e){return m4_has_children(w,e);}
